def click_text(page, text, tag=nil)
  result = page.evaluate(<<~JS)
    (() => {
      const els = Array.from(document.querySelectorAll('a,button,input[type="submit"]'));
      const el = els.find(e => {
        const t = (e.innerText || e.value || '').trim();
        return t === #{text.inspect};
      });
      if (!el) return 'not found: ' + els.map(e=>(e.innerText||e.value||'').trim()).join('|');
      el.scrollIntoView();
      el.click();
      return 'clicked';
    })()
