def fill_label(page, label, value)
  result = page.evaluate(<<~JS)
    (() => {
      const labels = Array.from(document.querySelectorAll('label'));
      const lab = labels.find(l => l.textContent.trim() === #{label.inspect});
      if (!lab) return 'label not found: ' + labels.map(l=>l.textContent.trim()).join('|');
      let control = null;
      if (lab.htmlFor) control = document.getElementById(lab.htmlFor);
      if (!control) control = lab.querySelector('input,textarea,select');
      if (!control) return 'no control for label';
      control.focus();
      control.value = '';
